import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Message {
  id: string;
  sender: 'user' | 'bot' | 'peer';
  text: string;
  timestamp: Date;
}

export interface UserProfile {
  name: string;
  role: 'warrior' | 'caregiver' | 'advocate' | 'doctor';
  location: string;
  age?: number;
}

export interface GameConcept {
  id: string;
  title: string;
  description: string;
  icon: string;
  color: string;
  category: 'RPG' | 'Action' | 'Puzzle' | 'Strategy' | 'Adventure';
}

export interface ForumPost {
  id: string;
  author: string;
  title: string;
  content: string;
  likes: number;
  comments: number;
  tags: string[];
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateHealthAdvice = async (query: string, userContext: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `User Query: ${query}\nUser Context: ${userContext}\nProvide empathetic, medically-grounded advice for someone with Sickle Cell Disease. Keep it simple and encouraging.`,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "I'm having trouble connecting right now. Please consult your local health provider.";
  }
};

export const generateAdvocacyPetition = async (issue: string, region: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a formal advocacy petition for ${issue} in ${region} related to Sickle Cell Disease. Include a compelling title, a background section, and three clear demands for policy change.`,
    });
    return response.text;
  } catch (error) {
    return "Failed to generate petition. Please try again.";
  }
};

export const generateGameStory = async (conceptTitle: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Create a short, engaging game introduction narrative for a game called "${conceptTitle}" which educates about Sickle Cell Disease. Make it feel heroic and urgent.`,
    });
    return response.text;
  } catch (error) {
    return "In a world where every breath counts, one warrior stands against the tide...";
  }
};

import React, { useState } from 'react';
import { HashRouter, Routes, Route, Link, useLocation } from 'react-router-dom';
import { 
  Home, 
  Gamepad2, 
  MessageSquare, 
  Video, 
  Users, 
  Megaphone, 
  User,
  Activity
} from 'lucide-react';
import Dashboard from './components/Dashboard';
import GamesHub from './components/GamesHub';
import ChatSystem from './components/ChatSystem';
import Telemedicine from './components/Telemedicine';
import Community from './components/Community';
import Advocacy from './components/Advocacy';

const Navigation = () => {
  const location = useLocation();
  const isActive = (path: string) => location.pathname === path;

  return (
    <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-4 py-2 flex justify-around items-center z-50 md:top-0 md:bottom-auto md:flex-col md:w-20 md:h-screen md:py-8">
      <NavItem to="/" icon={<Home size={24} />} label="Home" active={isActive('/')} />
      <NavItem to="/games" icon={<Gamepad2 size={24} />} label="Play" active={isActive('/games')} />
      <NavItem to="/chat" icon={<MessageSquare size={24} />} label="Chat" active={isActive('/chat')} />
      <NavItem to="/telemedicine" icon={<Video size={24} />} label="Care" active={isActive('/telemedicine')} />
      <NavItem to="/community" icon={<Users size={24} />} label="Group" active={isActive('/community')} />
      <NavItem to="/advocacy" icon={<Megaphone size={24} />} label="Act" active={isActive('/advocacy')} />
    </nav>
  );
};

const NavItem = ({ to, icon, label, active }: { to: string, icon: React.ReactNode, label: string, active: boolean }) => (
  <Link 
    to={to} 
    className={`flex flex-col items-center gap-1 transition-colors ${active ? 'text-red-600' : 'text-gray-400 hover:text-red-400'}`}
  >
    {icon}
    <span className="text-[10px] font-medium md:hidden">{label}</span>
  </Link>
);

const App: React.FC = () => {
  return (
    <HashRouter>
      <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
        <Navigation />
        <main className="flex-1 pb-20 md:pb-0 md:ml-20 overflow-y-auto">
          <header className="sticky top-0 bg-white shadow-sm px-4 py-4 flex items-center justify-between z-40">
            <div className="flex items-center gap-2">
              <div className="w-10 h-10 bg-red-600 rounded-full flex items-center justify-center text-white font-bold">W</div>
              <h1 className="text-xl font-bold text-gray-800">Warrior Cell</h1>
            </div>
            <div className="flex items-center gap-3">
              <Activity className="text-red-500 animate-pulse" />
              <div className="bg-gray-100 p-2 rounded-full">
                <User size={20} className="text-gray-600" />
              </div>
            </div>
          </header>

          <div className="p-4 max-w-5xl mx-auto">
            <Routes>
              <Route path="/" element={<Dashboard />} />
              <Route path="/games" element={<GamesHub />} />
              <Route path="/chat" element={<ChatSystem />} />
              <Route path="/telemedicine" element={<Telemedicine />} />
              <Route path="/community" element={<Community />} />
              <Route path="/advocacy" element={<Advocacy />} />
            </Routes>
          </div>
        </main>
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Heart, Droplets, Shield, Award, ChevronRight, Zap } from 'lucide-react';
import { SCD_FACTS } from '../constants';
import { generateHealthAdvice } from '../services/gemini';

const Dashboard: React.FC = () => {
  const [advice, setAdvice] = useState<string>("Loading your health tip...");
  const [isTyping, setIsTyping] = useState(false);

  useEffect(() => {
    const fetchAdvice = async () => {
      setIsTyping(true);
      const res = await generateHealthAdvice("Give me a daily tip for hydration and SCD.", "User is a 25-year-old warrior from Lagos.");
      setAdvice(res || "Drink plenty of water today!");
      setIsTyping(false);
    };
    fetchAdvice();
  }, []);

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      {/* AI Assistant Greeting */}
      <div className="bg-gradient-to-br from-red-600 to-red-800 rounded-2xl p-6 text-white shadow-lg">
        <div className="flex justify-between items-start mb-4">
          <div>
            <h2 className="text-2xl font-bold mb-1">Hello, Warrior!</h2>
            <p className="opacity-90">Your health dashboard is up to date.</p>
          </div>
          <Zap className="text-yellow-400" fill="currentColor" />
        </div>
        <div className="bg-white/10 backdrop-blur-md rounded-xl p-4 border border-white/20">
          <p className="text-sm font-medium mb-2 uppercase tracking-wider text-red-200 italic">Daily AI Insight</p>
          <p className="text-md leading-relaxed">
            {isTyping ? "AI is thinking..." : advice}
          </p>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-2 gap-4">
        <StatCard 
          icon={<Droplets className="text-blue-500" />} 
          label="Hydration" 
          value="1.8L" 
          goal="3.0L" 
          color="blue"
        />
        <StatCard 
          icon={<Shield className="text-green-500" />} 
          label="Crisis Risk" 
          value="Low" 
          goal="Avoid Triggers" 
          color="green"
        />
      </div>

      {/* Action Sections */}
      <section>
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-lg font-bold text-gray-800">Quick Actions</h3>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <ActionButton 
            title="Log Symptoms" 
            desc="Track pain levels & triggers"
            icon={<Heart className="text-red-500" />}
          />
          <ActionButton 
            title="SCD Academy" 
            desc="Learn about management"
            icon={<Award className="text-yellow-600" />}
          />
          <ActionButton 
            title="Find Support" 
            desc="Join a local group"
            icon={<Users className="text-blue-500" />}
          />
        </div>
      </section>

      {/* SCD Fact Slider Mock */}
      <section className="bg-yellow-50 border border-yellow-100 rounded-xl p-4">
        <h4 className="font-bold text-yellow-800 mb-2 flex items-center gap-2">
          <Zap size={16} /> Did You Know?
        </h4>
        <p className="text-yellow-900 text-sm">
          {SCD_FACTS[Math.floor(Math.random() * SCD_FACTS.length)]}
        </p>
      </section>
    </div>
  );
};

const StatCard = ({ icon, label, value, goal, color }: any) => (
  <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
    <div className="flex items-center gap-2 mb-2">
      {icon}
      <span className="text-sm text-gray-500 font-medium">{label}</span>
    </div>
    <div className="text-2xl font-bold text-gray-800">{value}</div>
    <div className="text-[10px] text-gray-400 mt-1 uppercase">Goal: {goal}</div>
  </div>
);

const ActionButton = ({ title, desc, icon }: any) => (
  <button className="flex items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-100 hover:border-red-200 transition-all text-left w-full group">
    <div className="bg-gray-50 p-3 rounded-lg group-hover:bg-red-50 transition-colors">
      {icon}
    </div>
    <div className="flex-1">
      <h4 className="font-bold text-gray-800">{title}</h4>
      <p className="text-xs text-gray-500">{desc}</p>
    </div>
    <ChevronRight size={18} className="text-gray-300" />
  </button>
);

export default Dashboard;

import React, { useState } from 'react';
import { Play, Info, Trophy, Star } from 'lucide-react';
import { GAME_CONCEPTS } from '../constants';
import { generateGameStory } from '../services/gemini';

const GamesHub: React.FC = () => {
  const [selectedGame, setSelectedGame] = useState<string | null>(null);
  const [narrative, setNarrative] = useState<string>("");
  const [loadingNarrative, setLoadingNarrative] = useState(false);

  const handleOpenGame = async (game: any) => {
    setSelectedGame(game.id);
    setLoadingNarrative(true);
    const story = await generateGameStory(game.title);
    setNarrative(story);
    setLoadingNarrative(false);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Warrior Quest</h2>
          <p className="text-gray-500 text-sm">Play and learn to earn rewards</p>
        </div>
        <div className="bg-yellow-100 px-3 py-1 rounded-full flex items-center gap-2 border border-yellow-200">
          <Trophy size={16} className="text-yellow-600" />
          <span className="text-yellow-700 font-bold">1,250 XP</span>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {GAME_CONCEPTS.map((game) => (
          <div 
            key={game.id}
            onClick={() => handleOpenGame(game)}
            className="relative overflow-hidden rounded-2xl cursor-pointer group hover:scale-[1.02] transition-transform shadow-md"
          >
            <div className={`${game.color} h-32 flex items-center justify-center text-5xl`}>
              {game.icon}
            </div>
            <div className="bg-white p-4">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="font-bold text-gray-800">{game.title}</h3>
                  <span className="text-[10px] bg-gray-100 px-2 py-0.5 rounded text-gray-500 font-bold uppercase tracking-tighter">
                    {game.category}
                  </span>
                </div>
                <div className="bg-red-50 p-2 rounded-full text-red-600">
                  <Play size={16} fill="currentColor" />
                </div>
              </div>
              <p className="text-xs text-gray-500 mt-2 line-clamp-2">
                {game.description}
              </p>
            </div>
          </div>
        ))}
      </div>

      {/* Game Modal Mockup */}
      {selectedGame && (
        <div className="fixed inset-0 bg-black/80 z-[60] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-3xl overflow-hidden shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="p-6">
              <div className="flex justify-between items-start mb-4">
                <h3 className="text-2xl font-bold game-font text-red-600">
                  {GAME_CONCEPTS.find(g => g.id === selectedGame)?.title}
                </h3>
                <button 
                  onClick={() => setSelectedGame(null)}
                  className="p-1 hover:bg-gray-100 rounded-full"
                >
                  ✕
                </button>
              </div>

              <div className="bg-gray-900 rounded-xl aspect-video flex flex-col items-center justify-center text-white mb-6 relative border-4 border-gray-800">
                <div className="text-center p-8">
                   {loadingNarrative ? (
                     <div className="flex gap-2">
                        <div className="w-2 h-2 bg-red-500 rounded-full animate-bounce"></div>
                        <div className="w-2 h-2 bg-red-500 rounded-full animate-bounce delay-100"></div>
                        <div className="w-2 h-2 bg-red-500 rounded-full animate-bounce delay-200"></div>
                     </div>
                   ) : (
                     <p className="italic text-sm text-gray-300 leading-relaxed">
                       {narrative}
                     </p>
                   )}
                </div>
                <button className="absolute bottom-4 bg-red-600 px-6 py-2 rounded-full font-bold hover:bg-red-700 transition-colors flex items-center gap-2">
                  <Play size={18} fill="currentColor" /> START MISSION
                </button>
              </div>

              <div className="space-y-4">
                <div className="flex items-center gap-3 text-sm text-gray-600">
                  <Star className="text-yellow-400" size={18} fill="currentColor" />
                  <span>Objective: Clear 5 blockages in the bloodstream</span>
                </div>
                <div className="flex items-center gap-3 text-sm text-gray-600">
                  <Info className="text-blue-400" size={18} />
                  <span>Reward: Advocacy Badge + 200 XP</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default GamesHub;

import React, { useState } from 'react';
import { Send, Search, MoreVertical, Paperclip, Phone, Video } from 'lucide-react';

const CHATS = [
  { id: '1', name: 'Lagos Warriors Support', lastMsg: 'Does anyone have a contact for...', time: '10:45 AM', unread: 3, online: true },
  { id: '2', name: 'Dr. Sarah (Hematology)', lastMsg: 'Your lab results are ready.', time: 'Yesterday', unread: 0, online: false },
  { id: '3', name: 'Global SCD Network', lastMsg: 'Meeting at 5PM GMT today!', time: 'Yesterday', unread: 0, online: true },
];

const ChatSystem: React.FC = () => {
  const [activeChat, setActiveChat] = useState<string | null>(CHATS[0].id);
  const [message, setMessage] = useState('');

  return (
    <div className="h-[calc(100vh-140px)] flex flex-col md:flex-row bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
      {/* Sidebar */}
      <div className={`w-full md:w-80 border-r border-gray-100 flex flex-col ${activeChat && 'hidden md:flex'}`}>
        <div className="p-4 bg-gray-50 border-b border-gray-100">
          <h2 className="text-xl font-bold mb-4">Messages</h2>
          <div className="relative">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={16} />
            <input 
              type="text" 
              placeholder="Search chats..." 
              className="w-full pl-10 pr-4 py-2 bg-white rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-1 focus:ring-red-500"
            />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {CHATS.map((chat) => (
            <div 
              key={chat.id}
              onClick={() => setActiveChat(chat.id)}
              className={`p-4 flex items-center gap-3 cursor-pointer hover:bg-gray-50 transition-colors ${activeChat === chat.id ? 'bg-red-50' : ''}`}
            >
              <div className="relative">
                <div className="w-12 h-12 bg-gray-200 rounded-full flex items-center justify-center text-gray-500 font-bold text-lg">
                  {chat.name[0]}
                </div>
                {chat.online && <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white rounded-full"></div>}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-baseline">
                  <h4 className="font-bold text-gray-800 truncate">{chat.name}</h4>
                  <span className="text-[10px] text-gray-400">{chat.time}</span>
                </div>
                <p className="text-xs text-gray-500 truncate">{chat.lastMsg}</p>
              </div>
              {chat.unread > 0 && (
                <div className="bg-red-600 text-white text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full">
                  {chat.unread}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Main Chat Area */}
      {activeChat ? (
        <div className="flex-1 flex flex-col">
          {/* Header */}
          <div className="p-4 border-b border-gray-100 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <button onClick={() => setActiveChat(null)} className="md:hidden text-gray-500">←</button>
              <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center text-gray-600 font-bold">
                {CHATS.find(c => c.id === activeChat)?.name[0]}
              </div>
              <div>
                <h4 className="font-bold text-gray-800 leading-none">{CHATS.find(c => c.id === activeChat)?.name}</h4>
                <span className="text-[10px] text-green-600 font-medium uppercase">Online</span>
              </div>
            </div>
            <div className="flex items-center gap-4 text-gray-400">
              <Video size={20} className="hover:text-red-500 cursor-pointer" />
              <Phone size={20} className="hover:text-red-500 cursor-pointer" />
              <MoreVertical size={20} className="hover:text-red-500 cursor-pointer" />
            </div>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50">
            <div className="flex flex-col items-center">
              <span className="text-[10px] bg-white px-2 py-1 rounded shadow-sm text-gray-400 mb-4">TODAY</span>
            </div>

            <ChatBubble text="Hello! How are you feeling today?" sender="peer" time="10:00 AM" />
            <ChatBubble text="I'm doing okay, just focusing on hydration. Did you see the new advocacy campaign?" sender="user" time="10:05 AM" />
            <ChatBubble text="Yes! I already signed the petition. It's so important for our community." sender="peer" time="10:06 AM" />
          </div>

          {/* Input */}
          <div className="p-4 border-t border-gray-100 flex items-center gap-3">
            <button className="text-gray-400 hover:text-red-500"><Paperclip size={20} /></button>
            <input 
              type="text" 
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              placeholder="Type a message..." 
              className="flex-1 px-4 py-2 bg-gray-100 rounded-full text-sm focus:outline-none"
            />
            <button className="bg-red-600 text-white p-2 rounded-full hover:bg-red-700 transition-colors shadow-sm">
              <Send size={20} fill="currentColor" />
            </button>
          </div>
        </div>
      ) : (
        <div className="flex-1 flex flex-col items-center justify-center text-gray-400 bg-gray-50">
          <MessageSquare size={48} className="mb-2 opacity-20" />
          <p>Select a chat to start messaging</p>
        </div>
      )}
    </div>
  );
};

const ChatBubble = ({ text, sender, time }: any) => (
  <div className={`flex ${sender === 'user' ? 'justify-end' : 'justify-start'}`}>
    <div className={`max-w-[80%] p-3 rounded-2xl shadow-sm text-sm ${sender === 'user' ? 'bg-red-600 text-white rounded-tr-none' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'}`}>
      <p>{text}</p>
      <span className={`text-[9px] block mt-1 ${sender === 'user' ? 'text-red-200' : 'text-gray-400'}`}>{time}</span>
    </div>
  </div>
);

export default ChatSystem;

import React, { useState } from 'react';
import { Megaphone, FileText, Send, Loader2, Sparkles, Copy, Globe } from 'lucide-react';
import { generateAdvocacyPetition } from '../services/gemini';

const Advocacy: React.FC = () => {
  const [issue, setIssue] = useState('');
  const [region, setRegion] = useState('');
  const [petition, setPetition] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleGenerate = async () => {
    if (!issue || !region) return;
    setLoading(true);
    const res = await generateAdvocacyPetition(issue, region);
    setPetition(res);
    setLoading(false);
  };

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-r from-purple-600 to-indigo-600 rounded-2xl p-6 text-white shadow-lg">
        <h2 className="text-2xl font-bold mb-2 flex items-center gap-2">
          <Megaphone className="rotate-[-10deg]" /> Voice of Warriors
        </h2>
        <p className="text-sm opacity-90">Use AI to create powerful advocacy tools and drive real-world policy change for SCD.</p>
      </div>

      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm space-y-4">
        <h3 className="font-bold text-gray-800 flex items-center gap-2">
          <Sparkles size={18} className="text-yellow-500" /> Advocacy Tool Generator
        </h3>

        <div className="space-y-3">
          <div>
            <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">What is the issue?</label>
            <input 
              type="text" 
              placeholder="e.g. Free hydroxyurea in schools" 
              value={issue}
              onChange={(e) => setIssue(e.target.value)}
              className="w-full px-4 py-2 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-1 focus:ring-purple-500"
            />
          </div>
          <div>
            <label className="text-xs font-bold text-gray-400 uppercase mb-1 block">Where is this for?</label>
            <div className="relative">
              <Globe className="absolute left-3 top-2.5 text-gray-400" size={18} />
              <input 
                type="text" 
                placeholder="e.g. Nairobi, Kenya" 
                value={region}
                onChange={(e) => setRegion(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-100 rounded-xl focus:outline-none focus:ring-1 focus:ring-purple-500"
              />
            </div>
          </div>
          <button 
            onClick={handleGenerate}
            disabled={loading || !issue || !region}
            className="w-full bg-purple-600 text-white font-bold py-3 rounded-xl hover:bg-purple-700 transition-colors flex items-center justify-center gap-2 disabled:opacity-50"
          >
            {loading ? <Loader2 className="animate-spin" /> : <FileText size={18} />}
            {loading ? 'Generating petition...' : 'Generate AI Petition'}
          </button>
        </div>
      </div>

      {petition && (
        <div className="bg-white p-6 rounded-2xl border border-purple-100 shadow-md animate-in slide-in-from-bottom-4 duration-300">
          <div className="flex justify-between items-center mb-4 pb-2 border-b border-gray-50">
            <h4 className="font-bold text-purple-800">Your AI-Generated Petition</h4>
