import React, { useState, useEffect, useRef } from 'react';
import { GameType } from '../types';
import { Play, RotateCcw, Award, CheckCircle2, Droplets, Zap, Shield, Heart, Zap as OxygenIcon } from 'lucide-react';

interface GameEngineProps {
  type: GameType;
  title: string;
  onComplete: (score: number) => void;
  onCancel: () => void;
}

const GameEngine: React.FC<GameEngineProps> = ({ type, title, onComplete, onCancel }) => {
  const [gameState, setGameState] = useState<'start' | 'playing' | 'end'>('start');
  const [score, setScore] = useState(0);
  const [timer, setTimer] = useState(30);
  const [extraData, setExtraData] = useState<any>(null);

  useEffect(() => {
    let interval: any;
    if (gameState === 'playing' && timer > 0) {
      interval = setInterval(() => setTimer(t => t - 1), 1000);
    } else if (timer === 0) {
      setGameState('end');
    }
    return () => clearInterval(interval);
  }, [gameState, timer]);

  const startGame = () => {
    setGameState('playing');
    setScore(0);
    setTimer(30);

    // Initialize specific game data
    if (type === 'cards') {
      const symbols = ['💧', '💊', '🛌', '🥦', '🧣', '🌡️'];
      const pairs = [...symbols, ...symbols].sort(() => Math.random() - 0.5);
      setExtraData({ cards: pairs.map((s, i) => ({ id: i, symbol: s, flipped: false, solved: false })), selected: [] });
    } else if (type === 'runner') {
      setExtraData({ pos: 1, obstacles: [] });
    } else if (type === 'strategy') {
      setExtraData({ hydration: 100, oxygen: 100 });
    } else if (type === 'defense') {
      setExtraData({ health: 100, enemies: [] });
    }
  };

  // --- GAME SPECIFIC LOGIC ---

  // 1. Cards (Sickle Cell Snap)
  const handleCardClick = (id: number) => {
    if (gameState !== 'playing') return;
    const { cards, selected } = extraData;
    if (selected.length === 2 || cards[id].flipped || cards[id].solved) return;

    const newCards = [...cards];
    newCards[id].flipped = true;
    const newSelected = [...selected, id];

    if (newSelected.length === 2) {
      if (newCards[newSelected[0]].symbol === newCards[newSelected[1]].symbol) {
        newCards[newSelected[0]].solved = true;
        newCards[newSelected[1]].solved = true;
        setScore(s => s + 10);
        setExtraData({ cards: newCards, selected: [] });
        if (newCards.every(c => c.solved)) setGameState('end');
      } else {
        setExtraData({ cards: newCards, selected: newSelected });
        setTimeout(() => {
          newCards[newSelected[0]].flipped = false;
          newCards[newSelected[1]].flipped = false;
          setExtraData({ cards: newCards, selected: [] });
        }, 1000);
      }
    } else {
      setExtraData({ cards: newCards, selected: newSelected });
    }
  };

  // 2. Runner (Red Cell Racer)
  useEffect(() => {
    if (type === 'runner' && gameState === 'playing') {
      const runInterval = setInterval(() => {
        setExtraData((prev: any) => {
          const newObs = prev.obstacles.map((o: any) => ({ ...o, y: o.y + 5 })).filter((o: any) => o.y < 100);
          if (Math.random() > 0.9) newObs.push({ x: Math.floor(Math.random() * 3), y: 0 });

          // Collision
          const collision = newObs.find((o: any) => o.x === prev.pos && o.y > 80 && o.y < 95);
          if (collision) {
             setGameState('end');
             return prev;
          }

          setScore(s => s + 1);
          return { ...prev, obstacles: newObs };
        });
      }, 50);
      return () => clearInterval(runInterval);
    }
  }, [type, gameState]);

  // 3. Strategy (SCD Survival)
  useEffect(() => {
    if (type === 'strategy' && gameState === 'playing') {
      const survivalInterval = setInterval(() => {
        setExtraData((prev: any) => {
          const h = Math.max(0, prev.hydration - 1.5);
          const o = Math.max(0, prev.oxygen - 1);
          if (h <= 0 || o <= 0) setGameState('end');
          setScore(s => s + 1);
          return { hydration: h, oxygen: o };
        });
      }, 200);
      return () => clearInterval(survivalInterval);
    }
  }, [type, gameState]);

  const renderGame = () => {
    switch (type) {
      case 'cards':
        return (
          <div className="grid grid-cols-4 gap-2 h-full content-center">
            {extraData?.cards.map((c: any) => (
              <div 
                key={c.id} 
                onClick={() => handleCardClick(c.id)}
                className={`aspect-square flex items-center justify-center text-2xl rounded-xl cursor-pointer transition-all duration-300 transform ${c.flipped || c.solved ? 'bg-white rotate-0' : 'bg-red-500 rotate-180'}`}
              >
                {(c.flipped || c.solved) ? c.symbol : '?'}
              </div>
            ))}
          </div>
        );
      case 'runner':
        return (
          <div className="relative w-full h-full bg-red-100 overflow-hidden rounded-xl border-4 border-red-200">
            <div className="absolute inset-0 flex">
              <div className="flex-1 border-r border-red-200/50"></div>
              <div className="flex-1 border-r border-red-200/50"></div>
              <div className="flex-1"></div>
            </div>
            {extraData?.obstacles.map((o: any, i: number) => (
              <div key={i} className="absolute text-3xl transition-all duration-75" style={{ left: `${o.x * 33 + 5}%`, top: `${o.y}%` }}>
                ⚡
              </div>
            ))}
            <div 
              className="absolute bottom-4 text-4xl transition-all duration-200" 
              style={{ left: `${extraData?.pos * 33 + 5}%` }}
            >
              🔴
            </div>
            <div className="absolute bottom-2 left-0 right-0 flex justify-center gap-4">
               <button onClick={() => setExtraData((p: any) => ({ ...p, pos: Math.max(0, p.pos - 1) }))} className="bg-white/50 p-2 rounded-full">←</button>
               <button onClick={() => setExtraData((p: any) => ({ ...p, pos: Math.min(2, p.pos + 1) }))} className="bg-white/50 p-2 rounded-full">→</button>
            </div>
          </div>
        );
      case 'strategy':
        return (
          <div className="flex flex-col items-center justify-center h-full gap-8">
            <div className="w-full space-y-4">
              <div>
                <div className="flex justify-between text-xs font-bold mb-1"><span className="flex items-center gap-1"><Droplets size={12}/> Hydration</span> <span>{Math.round(extraData?.hydration)}%</span></div>
                <div className="w-full bg-gray-200 h-4 rounded-full overflow-hidden">
                  <div className="bg-blue-500 h-full transition-all" style={{ width: `${extraData?.hydration}%` }}></div>
                </div>
                <button onClick={() => setExtraData((p: any) => ({ ...p, hydration: Math.min(100, p.hydration + 20) }))} className="mt-2 bg-blue-100 text-blue-700 text-xs px-3 py-1 rounded-full font-bold">DRINK WATER</button>
              </div>
              <div>
                <div className="flex justify-between text-xs font-bold mb-1"><span className="flex items-center gap-1"><OxygenIcon size={12}/> Oxygen</span> <span>{Math.round(extraData?.oxygen)}%</span></div>
                <div className="w-full bg-gray-200 h-4 rounded-full overflow-hidden">
                  <div className="bg-red-500 h-full transition-all" style={{ width: `${extraData?.oxygen}%` }}></div>
                </div>
                <button onClick={() => setExtraData((p: any) => ({ ...p, oxygen: Math.min(100, p.oxygen + 20) }))} className="mt-2 bg-red-100 text-red-700 text-xs px-3 py-1 rounded-full font-bold">DEEP BREATH</button>
              </div>
            </div>
          </div>
        );
      case 'defense':
        return (
          <div className="h-full flex flex-col items-center justify-center">
             <div className="relative w-64 h-64 border-4 border-emerald-200 rounded-full flex items-center justify-center bg-emerald-50 overflow-hidden">
                <div className="text-6xl animate-pulse">🏰</div>
                <div className="absolute inset-0">
                   {[...Array(5)].map((_, i) => (
                     <div key={i} className="absolute text-2xl animate-bounce cursor-pointer" style={{ 
                       left: `${Math.random() * 80 + 10}%`, 
                       top: `${Math.random() * 80 + 10}%` 
                     }} onClick={() => { setScore(s => s + 5); }}>⚡</div>
                   ))}
                </div>
             </div>
             <p className="mt-4 text-xs font-medium text-gray-500">Tap sickle cells to defend the vessel!</p>
          </div>
        );
      case 'puzzle':
      case 'escape':
        return (
          <div className="h-full flex flex-col items-center justify-center p-4">
             <div className="grid grid-cols-3 gap-2">
               {[...Array(9)].map((_, i) => (
                 <button key={i} onClick={() => setScore(s => s + 5)} className="w-16 h-16 bg-white border-2 border-green-100 rounded-lg flex items-center justify-center text-2xl hover:bg-green-50">
                    {i === 4 ? '🧩' : (Math.random() > 0.5 ? '🩸' : '🧬')}
                 </button>
               ))}
             </div>
             <p className="mt-4 text-xs font-medium text-gray-500">Clear the path for the blood flow!</p>
          </div>
        );
      default:
        return (
          <div className="h-full flex flex-col items-center justify-center text-center p-6 bg-gray-50 rounded-xl">
             <Zap className="text-red-500 mb-4" size={48} />
             <h3 className="font-bold text-gray-800 mb-2">Narrative Mode</h3>
             <p className="text-sm text-gray-500 mb-6">Explore the world and make critical choices for your Warrior.</p>
             <button onClick={() => setScore(s => s + 100)} className="bg-red-600 text-white px-6 py-2 rounded-full font-bold shadow-md">Complete Mission</button>
          </div>
        );
    }
  };

  return (
    <div className="flex flex-col h-full bg-white">
      {gameState === 'start' && (
        <div className="flex-1 flex flex-col items-center justify-center text-center p-8 space-y-6">
          <div className="text-6xl animate-bounce">🎮</div>
          <h3 className="text-3xl font-black game-font text-red-600 tracking-wider">{title}</h3>
          <p className="text-gray-500 max-w-xs">Ready to start your mission, Warrior? Every action counts towards global advocacy.</p>
          <button 
            onClick={startGame}
            className="group relative px-8 py-3 bg-red-600 rounded-full text-white font-black game-font tracking-widest text-xl hover:bg-red-700 transition-all shadow-xl hover:scale-105"
          >
            START GAME
          </button>
        </div>
      )}

      {gameState === 'playing' && (
        <div className="flex-1 flex flex-col p-4">
          <div className="flex justify-between items-center mb-4">
            <div className="flex items-center gap-4">
              <div className="bg-red-50 px-3 py-1 rounded-full border border-red-100">
                <span className="text-xs font-bold text-red-600">SCORE: {score}</span>
              </div>
              <div className={`px-3 py-1 rounded-full border ${timer < 10 ? 'bg-orange-50 border-orange-200 text-orange-600' : 'bg-gray-50 border-gray-100 text-gray-600'}`}>
                <span className="text-xs font-bold">TIME: {timer}s</span>
              </div>
            </div>
            <button onClick={onCancel} className="text-gray-400 hover:text-red-500"><XIcon /></button>
          </div>
          <div className="flex-1 bg-gray-50 rounded-2xl overflow-hidden relative">
            {renderGame()}
          </div>
        </div>
      )}

      {gameState === 'end' && (
        <div className="flex-1 flex flex-col items-center justify-center text-center p-8 space-y-6 animate-in zoom-in-95">
          <div className="w-20 h-20 bg-yellow-100 rounded-full flex items-center justify-center text-yellow-600 border-4 border-yellow-200">
            <Award size={40} />
          </div>
          <div>
            <h3 className="text-3xl font-black game-font text-gray-800">Mission Complete!</h3>
            <p className="text-gray-500 mt-2">You've successfully advocated for SCD research!</p>
          </div>
          <div className="bg-red-50 px-8 py-4 rounded-2xl border-2 border-red-100 w-full">
            <div className="text-4xl font-black text-red-600">{score}</div>
            <div className="text-[10px] text-red-400 font-bold uppercase tracking-widest">Experience Gained</div>
          </div>
          <div className="flex gap-3 w-full">
            <button 
              onClick={startGame}
              className="flex-1 flex items-center justify-center gap-2 py-3 bg-gray-100 rounded-xl font-bold text-gray-600 hover:bg-gray-200"
            >
              <RotateCcw size={18} /> RETRY
            </button>
            <button 
              onClick={() => onComplete(score)}
              className="flex-1 flex items-center justify-center gap-2 py-3 bg-red-600 rounded-xl font-bold text-white hover:bg-red-700 shadow-lg"
            >
              <CheckCircle2 size={18} /> FINISH
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const XIcon = () => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
);

export default GameEngine;

import React, { useState } from 'react';
