      {/* Game Modal / Overlay */}
      {selectedGame && (
        <div className="fixed inset-0 bg-black/80 z-[60] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-3xl overflow-hidden shadow-2xl animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">
            {!isPlaying ? (
              <div className="p-6">
                <div className="flex justify-between items-start mb-4">
                  <h3 className="text-2xl font-bold game-font text-red-600">
                    {currentGameOver?.title}
                  </h3>
                  <button 
                    onClick={() => setSelectedGame(null)}
                    className="p-1 hover:bg-gray-100 rounded-full"
                  >
                    <X size={24} />
                  </button>
                </div>

                <div className="bg-gray-900 rounded-xl aspect-video flex flex-col items-center justify-center text-white mb-6 relative border-4 border-gray-800 overflow-hidden">
                  <div className="text-center p-8 z-10">
                     {loadingNarrative ? (
                       <div className="flex gap-2">
                          <div className="w-2 h-2 bg-red-500 rounded-full animate-bounce"></div>
                          <div className="w-2 h-2 bg-red-500 rounded-full animate-bounce delay-100"></div>
                          <div className="w-2 h-2 bg-red-500 rounded-full animate-bounce delay-200"></div>
                       </div>
                     ) : (
                       <p className="italic text-sm text-gray-300 leading-relaxed max-h-40 overflow-y-auto no-scrollbar">
                         {narrative}
