export default GamesHub;

import React, { useState, useEffect, useCallback } from 'react';
import { GameType } from '../types';
import { 
  Play, RotateCcw, Award, CheckCircle2, Droplets, Zap, 
  Shield, Heart, Zap as OxygenIcon, User, MessageSquare, 
  ChevronUp, ChevronDown, ChevronLeft, ChevronRight,
  Home, Hospital, Info, Star
} from 'lucide-react';

interface GameEngineProps {
  type: GameType;
  title: string;
  onComplete: (score: number) => void;
  onCancel: () => void;
}

const RPG_MAP_SIZE = 8;
const INITIAL_PLAYER_POS = { x: 1, y: 1 };

const NPCs = [
  { id: 'nurse', x: 2, y: 4, name: 'Nurse Joy', icon: <Heart className="text-red-500" />, dialog: "Warrior! Remember to drink your 3 liters today. It keeps your cells flowing smoothly!", quest: 'hydration' },
  { id: 'doctor', x: 5, y: 2, name: 'Dr. Hematology', icon: <Hospital className="text-blue-500" />, dialog: "Genetic counseling is vital for understanding how SCD is passed down. Let's look at the DNA patterns.", quest: 'genetics' },
  { id: 'peer', x: 6, y: 6, name: 'Warrior Sam', icon: <User className="text-purple-500" />, dialog: "I find that deep breathing helps me stay calm when I feel a crisis coming. Try it with me!", quest: 'breathing' },
];

const GameEngine: React.FC<GameEngineProps> = ({ type, title, onComplete, onCancel }) => {
  const [gameState, setGameState] = useState<'start' | 'playing' | 'end'>('start');
  const [score, setScore] = useState(0);
  const [timer, setTimer] = useState(60);
  const [extraData, setExtraData] = useState<any>(null);
  const [dialog, setDialog] = useState<{ name: string; text: string } | null>(null);

  useEffect(() => {
    let interval: any;
    if (gameState === 'playing' && timer > 0) {
      interval = setInterval(() => setTimer(t => t - 1), 1000);
    } else if (timer === 0) {
      setGameState('end');
    }
    return () => clearInterval(interval);
  }, [gameState, timer]);

  const startGame = () => {
    setGameState('playing');
    setScore(0);
    setTimer(type === 'rpg' ? 120 : 30);
    setDialog(null);

    if (type === 'cards') {
      const symbols = ['💧', '💊', '🛌', '🥦', '🧣', '🌡️'];
      const pairs = [...symbols, ...symbols].sort(() => Math.random() - 0.5);
      setExtraData({ cards: pairs.map((s, i) => ({ id: i, symbol: s, flipped: false, solved: false })), selected: [] });
    } else if (type === 'runner') {
      setExtraData({ pos: 1, obstacles: [] });
    } else if (type === 'strategy') {
      setExtraData({ hydration: 100, oxygen: 100 });
    } else if (type === 'defense') {
      setExtraData({ health: 100, enemies: [] });
    } else if (type === 'rpg') {
      setExtraData({ player: { ...INITIAL_PLAYER_POS }, questsDone: [], discoveredNPCs: [] });
    }
  };

  const movePlayer = useCallback((dx: number, dy: number) => {
    if (gameState !== 'playing' || dialog) return;
    setExtraData((prev: any) => {
      const newX = Math.max(0, Math.min(RPG_MAP_SIZE - 1, prev.player.x + dx));
      const newY = Math.max(0, Math.min(RPG_MAP_SIZE - 1, prev.player.y + dy));

      // Check for NPC encounter
      const npc = NPCs.find(n => n.x === newX && n.y === newY);
      if (npc) {
        setDialog({ name: npc.name, text: npc.dialog });
        setScore(s => s + 50);
        return { 
          ...prev, 
          discoveredNPCs: [...new Set([...prev.discoveredNPCs, npc.id])],
          questsDone: [...new Set([...prev.questsDone, npc.id])]
        };
      }

      return { ...prev, player: { x: newX, y: newY } };
    });
  }, [gameState, dialog]);

  // Handle keyboard for RPG
  useEffect(() => {
    if (type !== 'rpg' || gameState !== 'playing') return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowUp') movePlayer(0, -1);
      if (e.key === 'ArrowDown') movePlayer(0, 1);
      if (e.key === 'ArrowLeft') movePlayer(-1, 0);
      if (e.key === 'ArrowRight') movePlayer(1, 0);
      if (e.key === ' ' || e.key === 'Enter') setDialog(null);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [type, gameState, movePlayer]);

  // Game specific logic for other types
  const handleCardClick = (id: number) => {
    if (gameState !== 'playing') return;
    const { cards, selected } = extraData;
    if (selected.length === 2 || cards[id].flipped || cards[id].solved) return;

    const newCards = [...cards];
    newCards[id].flipped = true;
    const newSelected = [...selected, id];

    if (newSelected.length === 2) {
      if (newCards[newSelected[0]].symbol === newCards[newSelected[1]].symbol) {
        newCards[newSelected[0]].solved = true;
        newCards[newSelected[1]].solved = true;
        setScore(s => s + 10);
        setExtraData({ cards: newCards, selected: [] });
        if (newCards.every(c => c.solved)) setGameState('end');
      } else {
        setExtraData({ cards: newCards, selected: newSelected });
        setTimeout(() => {
          newCards[newSelected[0]].flipped = false;
          newCards[newSelected[1]].flipped = false;
          setExtraData({ cards: newCards, selected: [] });
        }, 1000);
      }
    } else {
      setExtraData({ cards: newCards, selected: newSelected });
    }
  };

  useEffect(() => {
    if (type === 'runner' && gameState === 'playing') {
      const runInterval = setInterval(() => {
        setExtraData((prev: any) => {
          const newObs = prev.obstacles.map((o: any) => ({ ...o, y: o.y + 5 })).filter((o: any) => o.y < 100);
          if (Math.random() > 0.9) newObs.push({ x: Math.floor(Math.random() * 3), y: 0 });
          const collision = newObs.find((o: any) => o.x === prev.pos && o.y > 80 && o.y < 95);
          if (collision) { setGameState('end'); return prev; }
          setScore(s => s + 1);
          return { ...prev, obstacles: newObs };
        });
      }, 50);
      return () => clearInterval(runInterval);
    }
  }, [type, gameState]);

  useEffect(() => {
    if (type === 'strategy' && gameState === 'playing') {
      const survivalInterval = setInterval(() => {
        setExtraData((prev: any) => {
          const h = Math.max(0, prev.hydration - 1.5);
          const o = Math.max(0, prev.oxygen - 1);
          if (h <= 0 || o <= 0) setGameState('end');
          setScore(s => s + 1);
          return { hydration: h, oxygen: o };
        });
      }, 200);
      return () => clearInterval(survivalInterval);
    }
  }, [type, gameState]);

  const renderGame = () => {
    switch (type) {
      case 'rpg':
        return (
          <div className="relative w-full h-full flex flex-col bg-gray-100 overflow-hidden">
            <div className="flex-1 grid grid-cols-8 grid-rows-8 gap-1 p-2 bg-emerald-50 relative border-2 border-emerald-100">
              {/* Render Map Tiles */}
              {Array.from({ length: RPG_MAP_SIZE * RPG_MAP_SIZE }).map((_, i) => {
                const x = i % RPG_MAP_SIZE;
                const y = Math.floor(i / RPG_MAP_SIZE);
                const isWall = (x === 0 || y === 0 || x === 7 || y === 7) && !(x === 4 && y === 0);
                return (
                  <div key={i} className={`flex items-center justify-center rounded ${isWall ? 'bg-emerald-200' : 'bg-white/50'}`}>
                    {x === 4 && y === 0 && <Home className="text-emerald-600 opacity-40" size={24} />}
                  </div>
                );
              })}

              {/* Render NPCs */}
              {NPCs.map(npc => (
                <div 
                  key={npc.id} 
                  className="absolute w-[12.5%] h-[12.5%] flex items-center justify-center transition-all duration-300"
                  style={{ left: `${npc.x * 12.5}%`, top: `${npc.y * 12.5}%` }}
                >
                  <div className="bg-white p-1 rounded-full shadow-sm animate-pulse border-2 border-emerald-200">
                    {npc.icon}
                  </div>
                </div>
              ))}

              {/* Render Player */}
              <div 
                className="absolute w-[12.5%] h-[12.5%] flex items-center justify-center transition-all duration-200 z-10"
                style={{ left: `${extraData?.player.x * 12.5}%`, top: `${extraData?.player.y * 12.5}%` }}
              >
                <div className="bg-red-600 text-white p-2 rounded-xl shadow-lg transform scale-125 border-2 border-white">
                  <User size={20} />
                </div>
              </div>
            </div>

            {/* RPG Controls */}
            <div className="h-24 bg-white border-t border-gray-200 p-2 flex justify-between items-center px-4">
              <div className="flex flex-col gap-1">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Navigation</span>
                <div className="grid grid-cols-3 gap-1">
                  <div />
                  <button onClick={() => movePlayer(0, -1)} className="p-1.5 bg-gray-100 rounded hover:bg-gray-200"><ChevronUp size={16}/></button>
                  <div />
                  <button onClick={() => movePlayer(-1, 0)} className="p-1.5 bg-gray-100 rounded hover:bg-gray-200"><ChevronLeft size={16}/></button>
                  <button onClick={() => movePlayer(0, 1)} className="p-1.5 bg-gray-100 rounded hover:bg-gray-200"><ChevronDown size={16}/></button>
                  <button onClick={() => movePlayer(1, 0)} className="p-1.5 bg-gray-100 rounded hover:bg-gray-200"><ChevronRight size={16}/></button>
                </div>
              </div>
              <div className="text-right">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Inventory</span>
                <div className="flex gap-2 mt-1">
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${extraData?.questsDone.includes('nurse') ? 'bg-blue-100 text-blue-600' : 'bg-gray-100 text-gray-300'}`}><Droplets size={16}/></div>
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${extraData?.questsDone.includes('doctor') ? 'bg-purple-100 text-purple-600' : 'bg-gray-100 text-gray-300'}`}><Info size={16}/></div>
                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${extraData?.questsDone.includes('peer') ? 'bg-red-100 text-red-600' : 'bg-gray-100 text-gray-300'}`}><Star size={16}/></div>
                </div>
              </div>
            </div>

            {/* Dialog Box */}
            {dialog && (
              <div className="absolute bottom-28 left-4 right-4 bg-white rounded-2xl shadow-2xl border-2 border-emerald-100 p-4 animate-in slide-in-from-bottom-10 z-20">
                <div className="flex items-center gap-2 mb-2">
                  <div className="w-8 h-8 bg-emerald-100 rounded-full flex items-center justify-center"><MessageSquare size={16} className="text-emerald-600" /></div>
                  <span className="font-bold text-emerald-800 text-sm">{dialog.name}</span>
                </div>
                <p className="text-gray-600 text-sm italic leading-relaxed mb-4">"{dialog.text}"</p>
                <button 
                  onClick={() => setDialog(null)}
                  className="w-full bg-emerald-600 text-white font-bold py-2 rounded-xl text-sm hover:bg-emerald-700 transition-colors"
                >
                  Continue Journey
                </button>
              </div>
            )}
          </div>
        );
      case 'cards':
        return (
          <div className="grid grid-cols-4 gap-2 h-full content-center p-4">
            {extraData?.cards.map((c: any) => (
              <div 
                key={c.id} 
                onClick={() => handleCardClick(c.id)}
                className={`aspect-square flex items-center justify-center text-2xl rounded-xl cursor-pointer transition-all duration-300 transform shadow-sm ${c.flipped || c.solved ? 'bg-white rotate-0 border-2 border-red-100' : 'bg-red-500 rotate-180 text-transparent'}`}
              >
                {(c.flipped || c.solved) ? c.symbol : '?'}
              </div>
            ))}
          </div>
        );
      case 'runner':
        return (
          <div className="relative w-full h-full bg-red-100 overflow-hidden rounded-xl border-4 border-red-200">
            <div className="absolute inset-0 flex">
              <div className="flex-1 border-r border-red-200/50"></div>
              <div className="flex-1 border-r border-red-200/50"></div>
              <div className="flex-1"></div>
            </div>
            {extraData?.obstacles.map((o: any, i: number) => (
              <div key={i} className="absolute text-3xl transition-all duration-75" style={{ left: `${o.x * 33 + 5}%`, top: `${o.y}%` }}>
                ⚡
              </div>
            ))}
            <div 
              className="absolute bottom-4 text-4xl transition-all duration-200" 
              style={{ left: `${extraData?.pos * 33 + 5}%` }}
            >
              🔴
            </div>
            <div className="absolute bottom-2 left-0 right-0 flex justify-center gap-4 p-4">
               <button onClick={() => setExtraData((p: any) => ({ ...p, pos: Math.max(0, p.pos - 1) }))} className="bg-white p-3 rounded-full shadow-lg hover:scale-110 active:scale-90 transition-transform"><ChevronLeft size={24} className="text-red-600"/></button>
               <button onClick={() => setExtraData((p: any) => ({ ...p, pos: Math.min(2, p.pos + 1) }))} className="bg-white p-3 rounded-full shadow-lg hover:scale-110 active:scale-90 transition-transform"><ChevronRight size={24} className="text-red-600"/></button>
            </div>
          </div>
        );
      case 'strategy':
        return (
          <div className="flex flex-col items-center justify-center h-full gap-8 p-8">
            <div className="w-full space-y-8">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                <div className="flex justify-between text-xs font-black mb-2 uppercase tracking-widest text-blue-600"><span className="flex items-center gap-1"><Droplets size={14}/> Hydration</span> <span>{Math.round(extraData?.hydration)}%</span></div>
                <div className="w-full bg-blue-50 h-6 rounded-full overflow-hidden border-2 border-blue-100">
                  <div className="bg-blue-500 h-full transition-all duration-300" style={{ width: `${extraData?.hydration}%` }}></div>
                </div>
                <button onClick={() => setExtraData((p: any) => ({ ...p, hydration: Math.min(100, p.hydration + 20) }))} className="mt-4 w-full bg-blue-600 text-white text-xs py-3 rounded-xl font-bold shadow-md hover:bg-blue-700 active:scale-95 transition-all uppercase tracking-wider">REFRESH DRINK</button>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                <div className="flex justify-between text-xs font-black mb-2 uppercase tracking-widest text-red-600"><span className="flex items-center gap-1"><OxygenIcon size={14}/> Oxygen</span> <span>{Math.round(extraData?.oxygen)}%</span></div>
                <div className="w-full bg-red-50 h-6 rounded-full overflow-hidden border-2 border-red-100">
                  <div className="bg-red-500 h-full transition-all duration-300" style={{ width: `${extraData?.oxygen}%` }}></div>
                </div>
                <button onClick={() => setExtraData((p: any) => ({ ...p, oxygen: Math.min(100, p.oxygen + 20) }))} className="mt-4 w-full bg-red-600 text-white text-xs py-3 rounded-xl font-bold shadow-md hover:bg-red-700 active:scale-95 transition-all uppercase tracking-wider">DEEP BREATH</button>
              </div>
            </div>
          </div>
        );
      case 'defense':
        return (
          <div className="h-full flex flex-col items-center justify-center bg-emerald-50">
             <div className="relative w-72 h-72 border-8 border-emerald-200 rounded-full flex items-center justify-center bg-white shadow-inner overflow-hidden">
                <div className="text-7xl animate-pulse drop-shadow-lg">🏰</div>
                <div className="absolute inset-0">
                   {[...Array(6)].map((_, i) => (
                     <div key={i} className="absolute text-3xl animate-bounce cursor-pointer hover:scale-150 transition-transform" style={{ 
                       left: `${Math.random() * 80 + 10}%`, 
                       top: `${Math.random() * 80 + 10}%`,
                       animationDelay: `${Math.random() * 2}s`
                     }} onClick={() => { setScore(s => s + 5); }}>⚡</div>
                   ))}
                </div>
             </div>
             <p className="mt-8 text-sm font-black text-emerald-800 uppercase tracking-widest animate-pulse">Tap sickle cells to defend!</p>
          </div>
        );
      case 'puzzle':
      case 'escape':
        return (
          <div className="h-full flex flex-col items-center justify-center p-6 bg-green-50">
             <div className="grid grid-cols-3 gap-3">
               {[...Array(9)].map((_, i) => (
                 <button key={i} onClick={() => setScore(s => s + 5)} className="w-20 h-20 bg-white border-4 border-green-100 rounded-2xl flex items-center justify-center text-4xl hover:bg-green-100 active:scale-90 transition-all shadow-sm">
                    {i === 4 ? '🧩' : (Math.random() > 0.5 ? '🩸' : '🧬')}
                 </button>
               ))}
             </div>
             <p className="mt-8 text-sm font-black text-green-800 uppercase tracking-widest">Connect the vessels!</p>
          </div>
        );
      default:
        return (
          <div className="h-full flex flex-col items-center justify-center text-center p-8 bg-gray-50 rounded-xl border-4 border-dashed border-gray-200">
             <Zap className="text-red-500 mb-6 animate-bounce" size={64} />
             <h3 className="font-black game-font text-3xl text-gray-800 mb-4 tracking-wider">{title}</h3>
             <p className="text-gray-500 mb-8 max-w-xs leading-relaxed">Advance your knowledge and advocate for the community. Ready to start?</p>
             <button onClick={() => setScore(s => s + 100)} className="bg-red-600 text-white px-10 py-3 rounded-full font-black text-xl shadow-xl hover:bg-red-700 transform hover:scale-105 active:scale-95 transition-all">START MISSION</button>
          </div>
        );
    }
  };

  return (
    <div className="flex flex-col h-full bg-white">
      {gameState === 'start' && (
        <div className="flex-1 flex flex-col items-center justify-center text-center p-8 space-y-8 bg-gradient-to-b from-white to-red-50">
          <div className="relative">
            <div className="absolute -inset-4 bg-red-500/10 rounded-full blur-2xl animate-pulse"></div>
            <div className="text-8xl relative drop-shadow-2xl">{type === 'rpg' ? '🛡️' : '🎮'}</div>
          </div>
          <div className="space-y-2">
            <h3 className="text-4xl font-black game-font text-red-600 tracking-widest">{title}</h3>
            <p className="text-gray-400 text-xs font-bold uppercase tracking-widest">{type} Mission</p>
          </div>
          <p className="text-gray-500 max-w-xs text-sm leading-relaxed">
            Your mission contributes to global Sickle Cell awareness. Earn XP and unlock advocacy tools.
          </p>
          <button 
            onClick={startGame}
            className="group relative px-12 py-4 bg-red-600 rounded-full text-white font-black game-font tracking-widest text-2xl hover:bg-red-700 transition-all shadow-2xl hover:scale-105 active:scale-95"
          >
            LAUNCH MISSION
          </button>
        </div>
      )}

      {gameState === 'playing' && (
        <div className="flex-1 flex flex-col">
          <div className="flex justify-between items-center p-4 border-b border-gray-100 bg-white">
            <div className="flex items-center gap-3">
              <div className="bg-red-600 p-2 rounded-lg text-white shadow-lg shadow-red-500/20">
                <Zap size={16} fill="currentColor" />
              </div>
              <div className="flex flex-col">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-none mb-1">XP Points</span>
                <span className="text-lg font-black text-gray-800 leading-none">{score}</span>
              </div>
            </div>
            <div className="flex items-center gap-4">
              <div className={`flex items-center gap-2 px-4 py-2 rounded-full border-2 transition-colors ${timer < 15 ? 'bg-red-50 border-red-200 text-red-600 animate-pulse' : 'bg-gray-50 border-gray-100 text-gray-600'}`}>
                <span className="text-sm font-black tracking-tighter">{Math.floor(timer / 60)}:{(timer % 60).toString().padStart(2, '0')}</span>
              </div>
              <button onClick={onCancel} className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-full transition-all"><XIcon /></button>
            </div>
          </div>
          <div className="flex-1 overflow-hidden relative">
            {renderGame()}
          </div>
        </div>
      )}

      {gameState === 'end' && (
        <div className="flex-1 flex flex-col items-center justify-center text-center p-8 space-y-8 animate-in zoom-in-95 bg-white">
          <div className="relative">
            <div className="absolute -inset-6 bg-yellow-400/20 rounded-full blur-3xl animate-pulse"></div>
            <div className="w-24 h-24 bg-gradient-to-br from-yellow-300 to-yellow-500 rounded-3xl flex items-center justify-center text-white border-4 border-white shadow-2xl transform rotate-12 relative">
              <Award size={56} />
            </div>
          </div>
          <div>
            <h3 className="text-4xl font-black game-font text-gray-800 tracking-wider">Mission Accomplished!</h3>
            <p className="text-gray-500 mt-2 font-medium">You've unlocked new advocacy tools for the community.</p>
          </div>
          <div className="bg-gradient-to-br from-red-600 to-red-800 px-10 py-6 rounded-[2rem] border-4 border-white shadow-2xl w-full max-w-sm transform -rotate-2">
            <div className="text-5xl font-black text-white drop-shadow-md">+{score}</div>
            <div className="text-[10px] text-red-200 font-black uppercase tracking-[0.2em] mt-2">Warrior XP Gained</div>
          </div>
          <div className="flex gap-4 w-full max-w-sm">
            <button 
              onClick={startGame}
              className="flex-1 flex items-center justify-center gap-2 py-4 bg-gray-100 rounded-2xl font-black text-gray-600 hover:bg-gray-200 transition-all text-sm uppercase tracking-wider"
            >
              <RotateCcw size={18} /> Retry
            </button>
            <button 
              onClick={() => onComplete(score)}
              className="flex-1 flex items-center justify-center gap-2 py-4 bg-red-600 rounded-2xl font-black text-white hover:bg-red-700 shadow-xl transition-all text-sm uppercase tracking-widest"
            >
              <CheckCircle2 size={18} /> Continue
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

const XIcon = () => (
  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
);

export default GameEngine;

import React, { useState, useEffect, useCallback } from 'react';
import { GameType } from '../types';
import { 
  Play, RotateCcw, Award, CheckCircle2, Droplets, Zap, 
  Shield, Heart, Zap as OxygenIcon, User, MessageSquare, 
  ChevronUp, ChevronDown, ChevronLeft, ChevronRight,
  Home, Hospital, Info, Star, X
} from 'lucide-react';

interface GameEngineProps {
  type: GameType;
  title: string;
  onComplete: (score: number) => void;
  onCancel: () => void;
}

const RPG_MAP_SIZE = 8;
const INITIAL_PLAYER_POS = { x: 1, y: 1 };

interface NPC {
  id: string;
  x: number;
  y: number;
  name: string;
  icon: React.ReactNode;
  dialog: string;
  questType: GameType | null;
}

const NPCs: NPC[] = [
  { 
    id: 'nurse', 
    x: 2, 
    y: 5, 
    name: 'Nurse Joy', 
    icon: <Heart className="text-red-500" />, 
    dialog: "Warrior! Your hydration levels are dropping. Complete the Hydration Challenge to keep your blood flowing!", 
    questType: 'strategy' 
  },
  { 
    id: 'doctor', 
    x: 5, 
    y: 2, 
    name: 'Dr. Hematology', 
    icon: <Hospital className="text-blue-500" />, 
    dialog: "Let's study the patterns of Sickle Cell inheritance. Match the traits in this genetic puzzle!", 
    questType: 'cards' 
  },
  { 
    id: 'peer', 
    x: 6, 
    y: 6, 
    name: 'Warrior Sam', 
    icon: <User className="text-purple-500" />, 
    dialog: "Sometimes the path gets blocked. Help me clear these vessels so we can both stay healthy!", 
    questType: 'puzzle' 
  },
];

const GameEngine: React.FC<GameEngineProps> = ({ type, title, onComplete, onCancel }) => {
  const [gameState, setGameState] = useState<'start' | 'playing' | 'end'>('start');
  const [score, setScore] = useState(0);
  const [timer, setTimer] = useState(60);
  const [extraData, setExtraData] = useState<any>(null);
  const [dialog, setDialog] = useState<{ npc: NPC; text: string } | null>(null);
  const [activeQuest, setActiveQuest] = useState<GameType | null>(null);

  // --- MAIN LOOP ---
  useEffect(() => {
    let interval: any;
    if (gameState === 'playing' && timer > 0 && !dialog && !activeQuest) {
      interval = setInterval(() => setTimer(t => t - 1), 1000);
    } else if (timer === 0) {
      setGameState('end');
    }
    return () => clearInterval(interval);
  }, [gameState, timer, dialog, activeQuest]);

  const startGame = () => {
    setGameState('playing');
    setScore(0);
    setTimer(type === 'rpg' ? 300 : 45); // RPG gives more time for exploration
    setDialog(null);
    setActiveQuest(null);
    initializeData(type);
  };

  const initializeData = (gameType: GameType) => {
    if (gameType === 'cards') {
      const symbols = ['💧', '💊', '🛌', '🥦', '🧣', '🌡️'];
      const pairs = [...symbols, ...symbols].sort(() => Math.random() - 0.5);
      setExtraData({ cards: pairs.map((s, i) => ({ id: i, symbol: s, flipped: false, solved: false })), selected: [] });
    } else if (gameType === 'runner') {
      setExtraData({ pos: 1, obstacles: [] });
    } else if (gameType === 'strategy') {
      setExtraData({ hydration: 100, oxygen: 100 });
    } else if (gameType === 'defense') {
      setExtraData({ health: 100, enemies: [] });
    } else if (gameType === 'rpg') {
      setExtraData({ player: { ...INITIAL_PLAYER_POS }, questsDone: [], discoveredNPCs: [] });
    } else {
      setExtraData({});
    }
  };

  // --- RPG NAVIGATION ---
  const movePlayer = useCallback((dx: number, dy: number) => {
    if (gameState !== 'playing' || dialog || activeQuest) return;
    setExtraData((prev: any) => {
      const newX = Math.max(0, Math.min(RPG_MAP_SIZE - 1, prev.player.x + dx));
      const newY = Math.max(0, Math.min(RPG_MAP_SIZE - 1, prev.player.y + dy));

      // Collision with boundary visuals (optional complexity)
      const isWall = (newX === 0 || newY === 0 || newX === 7 || newY === 7) && !(newX === 4 && newY === 0);
      if (isWall) return prev;

      // Check for NPC encounter
      const npc = NPCs.find(n => n.x === newX && n.y === newY);
      if (npc) {
        setDialog({ npc, text: npc.dialog });
        return { 
          ...prev, 
          player: { x: newX, y: newY }, // Move onto the tile
          discoveredNPCs: [...new Set([...prev.discoveredNPCs, npc.id])]
        };
      }

      return { ...prev, player: { x: newX, y: newY } };
    });
  }, [gameState, dialog, activeQuest]);

  useEffect(() => {
    if (type !== 'rpg' || gameState !== 'playing') return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowUp' || e.key === 'w') movePlayer(0, -1);
      if (e.key === 'ArrowDown' || e.key === 's') movePlayer(0, 1);
      if (e.key === 'ArrowLeft' || e.key === 'a') movePlayer(-1, 0);
      if (e.key === 'ArrowRight' || e.key === 'd') movePlayer(1, 0);
      if (e.key === ' ' || e.key === 'Enter') {
        if (dialog) handleStartQuest();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [type, gameState, movePlayer, dialog]);

  const handleStartQuest = () => {
    if (dialog?.npc.questType) {
      setActiveQuest(dialog.npc.questType);
      initializeData(dialog.npc.questType);
      setDialog(null);
    } else {
      setDialog(null);
    }
  };

  const handleQuestComplete = (points: number) => {
    setScore(s => s + points + 100);
    setExtraData((prev: any) => ({
      ...prev,
      player: prev.player, // Keep position
      questsDone: [...new Set([...prev.questsDone, dialog?.npc.id || ''])]
    }));
    setActiveQuest(null);
    // If all quests done, maybe end game?
    if (extraData?.questsDone.length + 1 >= NPCs.length) {
       setTimeout(() => setGameState('end'), 1000);
    }
  };

  // --- MINI GAME LOGIC ---

  // Sickle Cell Snap (Cards)
  const handleCardClick = (id: number) => {
    const { cards, selected } = extraData;
    if (selected.length === 2 || cards[id].flipped || cards[id].solved) return;
    const newCards = [...cards];
    newCards[id].flipped = true;
    const newSelected = [...selected, id];
    if (newSelected.length === 2) {
      if (newCards[newSelected[0]].symbol === newCards[newSelected[1]].symbol) {
        newCards[newSelected[0]].solved = true;
        newCards[newSelected[1]].solved = true;
        setExtraData({ cards: newCards, selected: [] });
        if (newCards.every(c => c.solved)) {
           if (type === 'rpg') handleQuestComplete(200); else setGameState('end');
        }
      } else {
        setExtraData({ cards: newCards, selected: newSelected });
        setTimeout(() => {
          newCards[newSelected[0]].flipped = false;
          newCards[newSelected[1]].flipped = false;
          setExtraData({ cards: newCards, selected: [] });
        }, 1000);
      }
    } else {
      setExtraData({ cards: newCards, selected: newSelected });
    }
  };

  // Strategy / Survival
  useEffect(() => {
    const activeType = activeQuest || type;
    if (activeType === 'strategy' && gameState === 'playing' && !dialog) {
      const interval = setInterval(() => {
        setExtraData((prev: any) => {
          if (!prev.hydration) return prev;
          const h = Math.max(0, prev.hydration - 1);
          const o = Math.max(0, prev.oxygen - 0.5);
          if (h <= 0 || o <= 0) {
            if (type === 'rpg') setActiveQuest(null); else setGameState('end');
          }
          if (h > 95 && o > 95 && type === 'rpg') {
             // Survival goal in RPG: Keep high for 5 seconds?
             // Simple version: click enough times.
          }
          return { ...prev, hydration: h, oxygen: o };
        });
      }, 100);
      return () => clearInterval(interval);
    }
  }, [activeQuest, type, gameState, dialog]);

  const renderGame = () => {
    const activeType = activeQuest || type;

    switch (activeType) {
      case 'rpg':
        return (
          <div className="relative w-full h-full flex flex-col bg-gray-100 overflow-hidden">
            <div className="flex-1 grid grid-cols-8 grid-rows-8 gap-0 p-2 bg-emerald-50 relative border-b border-emerald-100 shadow-inner">
              {Array.from({ length: RPG_MAP_SIZE * RPG_MAP_SIZE }).map((_, i) => {
                const x = i % RPG_MAP_SIZE;
                const y = Math.floor(i / RPG_MAP_SIZE);
                const isWall = (x === 0 || y === 0 || x === 7 || y === 7) && !(x === 4 && y === 0);
                return (
                  <div key={i} className={`flex items-center justify-center border-[0.5px] border-emerald-100/30 ${isWall ? 'bg-emerald-200' : 'bg-white/40'}`}>
                    {x === 4 && y === 0 && <Home className="text-emerald-600 opacity-30" size={24} />}
                  </div>
                );
              })}

              {NPCs.map(npc => (
                <div 
                  key={npc.id} 
                  className="absolute w-[12.5%] h-[12.5%] flex items-center justify-center transition-all duration-300"
                  style={{ left: `${npc.x * 12.5}%`, top: `${npc.y * 12.5}%` }}
                >
                  <div className={`p-1.5 rounded-full shadow-md animate-bounce border-2 bg-white ${extraData?.questsDone.includes(npc.id) ? 'border-gray-200 opacity-50 grayscale' : 'border-emerald-300 shadow-emerald-200'}`}>
                    {npc.icon}
                  </div>
                </div>
              ))}

              <div 
                className="absolute w-[12.5%] h-[12.5%] flex items-center justify-center transition-all duration-200 z-10"
                style={{ left: `${extraData?.player.x * 12.5}%`, top: `${extraData?.player.y * 12.5}%` }}
              >
                <div className="bg-red-600 text-white p-2 rounded-xl shadow-xl transform scale-125 border-2 border-white flex items-center justify-center">
                  <User size={20} fill="currentColor" />
                  <div className="absolute -top-1 -right-1 w-3 h-3 bg-green-500 rounded-full border-2 border-white animate-ping"></div>
                </div>
              </div>
            </div>

            <div className="h-28 bg-white border-t border-gray-100 p-4 flex justify-between items-center shadow-2xl">
              <div className="flex flex-col gap-2">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-none">Quest Progress</span>
                <div className="flex gap-3">
                  {NPCs.map(npc => (
                    <div key={npc.id} className={`w-10 h-10 rounded-xl flex items-center justify-center border-2 transition-all ${extraData?.questsDone.includes(npc.id) ? 'bg-green-50 border-green-200 text-green-600' : 'bg-gray-50 border-gray-100 text-gray-300'}`}>
                      {npc.icon}
                    </div>
                  ))}
                </div>
              </div>
              <div className="flex flex-col items-end gap-2">
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest leading-none">Controls</span>
                <div className="grid grid-cols-3 gap-1">
                  <div />
                  <button onClick={() => movePlayer(0, -1)} className="p-2 bg-gray-50 rounded-lg border border-gray-200 hover:bg-red-50 hover:text-red-600 transition-all"><ChevronUp size={14}/></button>
                  <div />
                  <button onClick={() => movePlayer(-1, 0)} className="p-2 bg-gray-50 rounded-lg border border-gray-200 hover:bg-red-50 hover:text-red-600 transition-all"><ChevronLeft size={14}/></button>
                  <button onClick={() => movePlayer(0, 1)} className="p-2 bg-gray-50 rounded-lg border border-gray-200 hover:bg-red-50 hover:text-red-600 transition-all"><ChevronDown size={14}/></button>
                  <button onClick={() => movePlayer(1, 0)} className="p-2 bg-gray-50 rounded-lg border border-gray-200 hover:bg-red-50 hover:text-red-600 transition-all"><ChevronRight size={14}/></button>
                </div>
              </div>
            </div>

            {dialog && (
              <div className="absolute inset-0 bg-black/40 backdrop-blur-[2px] z-20 flex items-center justify-center p-6">
                <div className="bg-white rounded-[2rem] shadow-2xl border-4 border-emerald-100 p-8 max-w-sm w-full animate-in zoom-in-95 duration-200">
                  <div className="flex items-center gap-4 mb-6">
                    <div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center text-3xl shadow-inner">{dialog.npc.icon}</div>
                    <div>
                      <h4 className="font-black text-emerald-800 text-xl tracking-tight leading-none">{dialog.npc.name}</h4>
                      <p className="text-[10px] font-bold text-emerald-500 uppercase tracking-[0.2em] mt-1">Village Elder</p>
                    </div>
                  </div>
                  <p className="text-gray-600 text-md italic leading-relaxed mb-8">"{dialog.text}"</p>
                  <div className="flex gap-3">
                    <button 
                      onClick={() => setDialog(null)}
                      className="flex-1 bg-gray-100 text-gray-500 font-bold py-3 rounded-2xl text-sm hover:bg-gray-200 transition-all"
                    >
                      Later
                    </button>
                    <button 
                      onClick={handleStartQuest}
                      className="flex-2 bg-emerald-600 text-white font-black py-4 px-6 rounded-2xl text-sm hover:bg-emerald-700 shadow-lg shadow-emerald-200 transition-all flex items-center justify-center gap-2"
                    >
                      <Zap size={16} fill="currentColor"/> START MISSION
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>
        );
      case 'cards':
        return (
          <div className="h-full flex flex-col p-6 bg-red-50">
            <h4 className="text-center font-black game-font text-red-600 mb-6 tracking-widest">Genetic Matcher</h4>
            <div className="grid grid-cols-4 gap-3 max-w-sm mx-auto">
              {extraData?.cards.map((c: any) => (
                <div 
                  key={c.id} 
                  onClick={() => handleCardClick(c.id)}
                  className={`aspect-square flex items-center justify-center text-3xl rounded-2xl cursor-pointer transition-all duration-500 transform shadow-md border-2 ${c.flipped || c.solved ? 'bg-white rotate-0 border-red-100' : 'bg-red-600 rotate-180 border-red-700'}`}
                >
                  {(c.flipped || c.solved) ? c.symbol : <div className="text-white font-black text-sm">?</div>}
                </div>
              ))}
            </div>
            {activeQuest && <button onClick={() => setActiveQuest(null)} className="mt-8 text-red-600 font-bold text-xs uppercase tracking-widest">Cancel Quest</button>}
          </div>
        );
      case 'strategy':
        return (
          <div className="h-full flex flex-col items-center justify-center p-8 bg-blue-50">
            <div className="w-full max-w-sm space-y-8">
              <div className="bg-white p-6 rounded-3xl shadow-xl border border-blue-100">
                <div className="flex justify-between text-[10px] font-black mb-2 uppercase tracking-widest text-blue-600"><span className="flex items-center gap-1"><Droplets size={14}/> Hydration</span> <span>{Math.round(extraData?.hydration)}%</span></div>
                <div className="w-full bg-blue-50 h-8 rounded-full overflow-hidden border-2 border-blue-100 p-1">
                  <div className="bg-blue-500 h-full rounded-full transition-all duration-300" style={{ width: `${extraData?.hydration}%` }}></div>
                </div>
                <button onClick={() => {
                  setExtraData((p: any) => ({ ...p, hydration: Math.min(100, p.hydration + 25) }));
                  if (activeQuest && extraData.hydration > 80) handleQuestComplete(50);
                }} className="mt-4 w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-lg hover:bg-blue-700 active:scale-95 transition-all text-sm uppercase tracking-[0.2em]">Drink Water</button>
              </div>
              <div className="bg-white p-6 rounded-3xl shadow-xl border border-red-100">
                <div className="flex justify-between text-[10px] font-black mb-2 uppercase tracking-widest text-red-600"><span className="flex items-center gap-1"><OxygenIcon size={14}/> Oxygen</span> <span>{Math.round(extraData?.oxygen)}%</span></div>
                <div className="w-full bg-red-50 h-8 rounded-full overflow-hidden border-2 border-red-100 p-1">
                  <div className="bg-red-500 h-full rounded-full transition-all duration-300" style={{ width: `${extraData?.oxygen}%` }}></div>
                </div>
                <button onClick={() => setExtraData((p: any) => ({ ...p, oxygen: Math.min(100, p.oxygen + 20) }))} className="mt-4 w-full bg-red-600 text-white font-black py-4 rounded-2xl shadow-lg hover:bg-red-700 active:scale-95 transition-all text-sm uppercase tracking-[0.2em]">Deep Breath</button>
              </div>
            </div>
          </div>
        );
      case 'puzzle':
        return (
          <div className="h-full flex flex-col items-center justify-center p-8 bg-green-50">
            <h4 className="font-black game-font text-green-700 mb-8 tracking-widest text-2xl">Vessel Flow</h4>
            <div className="grid grid-cols-3 gap-4 max-w-xs mx-auto">
              {[...Array(9)].map((_, i) => (
                <button 
                  key={i} 
                  onClick={() => {
                    setScore(s => s + 5);
                    if (activeQuest && Math.random() > 0.8) handleQuestComplete(150);
                  }} 
                  className="w-20 h-20 bg-white border-4 border-green-100 rounded-3xl flex items-center justify-center text-4xl hover:bg-green-100 active:scale-90 transition-all shadow-xl shadow-green-200/50"
