import React, { useState, useRef, useEffect } from 'react';
import { Send, Search, MoreVertical, Paperclip, Phone, Video, MessageSquare, ChevronLeft } from 'lucide-react';

const INITIAL_CHATS = [
  { id: '1', name: 'Lagos Warriors Support', lastMsg: 'Stay hydrated everyone!', time: '10:45 AM', unread: 3, online: true },
  { id: '2', name: 'Dr. Sarah (Hematology)', lastMsg: 'Your lab results are ready.', time: 'Yesterday', unread: 0, online: false },
  { id: '3', name: 'Global SCD Network', lastMsg: 'Meeting at 5PM GMT today!', time: 'Yesterday', unread: 0, online: true },
];

const ChatSystem: React.FC = () => {
  const [activeChatId, setActiveChatId] = useState<string | null>(INITIAL_CHATS[0].id);
  const [inputText, setInputText] = useState('');
  const [messages, setMessages] = useState<Record<string, any[]>>({
    '1': [
      { id: 1, text: "Hello Warriors! How's the hydration plan going?", sender: 'peer', time: '10:00 AM' },
      { id: 2, text: "Just finished my 2nd liter!", sender: 'peer', time: '10:05 AM' },
    ],
    '2': [{ id: 1, text: "Your recent tests show stable hemoglobin levels. Keep it up.", sender: 'peer', time: 'Yesterday' }],
    '3': [{ id: 1, text: "Reminder: World Sickle Cell Day planning starts now.", sender: 'peer', time: '9:00 AM' }]
  });

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, activeChatId]);

  const activeChat = INITIAL_CHATS.find(c => c.id === activeChatId);

  const handleSendMessage = () => {
    if (!inputText.trim() || !activeChatId) return;

    const newMessage = {
      id: Date.now(),
      text: inputText,
      sender: 'user',
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => ({
      ...prev,
      [activeChatId]: [...(prev[activeChatId] || []), newMessage]
    }));
    setInputText('');

    // Simulate auto-reply
    setTimeout(() => {
      const reply = {
        id: Date.now() + 1,
        text: "That's great to hear! Let's keep supporting each other. 💪",
        sender: 'peer',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      setMessages(prev => ({
        ...prev,
        [activeChatId]: [...(prev[activeChatId] || []), reply]
      }));
    }, 2000);
  };

  return (
    <div className="h-[calc(100vh-140px)] flex flex-col md:flex-row bg-white rounded-3xl shadow-xl border border-gray-100 overflow-hidden">
      {/* Sidebar */}
      <div className={`w-full md:w-80 border-r border-gray-100 flex flex-col ${activeChatId && 'hidden md:flex'}`}>
        <div className="p-6 bg-gray-50 border-b border-gray-100">
          <h2 className="text-2xl font-black text-gray-800 mb-4 tracking-tight">Warrior Chat</h2>
          <div className="relative">
            <Search className="absolute left-3 top-3 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Search conversations..." 
              className="w-full pl-10 pr-4 py-3 bg-white rounded-2xl border border-gray-100 text-sm focus:outline-none focus:ring-2 focus:ring-red-500/20"
            />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {INITIAL_CHATS.map((chat) => (
            <div 
              key={chat.id}
              onClick={() => setActiveChatId(chat.id)}
              className={`p-4 flex items-center gap-4 cursor-pointer hover:bg-gray-50 transition-all border-b border-gray-50/50 ${activeChatId === chat.id ? 'bg-red-50 border-red-100' : ''}`}
            >
              <div className="relative">
                <div className="w-14 h-14 bg-gradient-to-br from-red-100 to-red-200 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl shadow-sm">
                  {chat.name[0]}
                </div>
                {chat.online && <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-4 border-white rounded-full"></div>}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-center mb-1">
                  <h4 className="font-bold text-gray-800 truncate text-sm">{chat.name}</h4>
                  <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">{chat.time}</span>
                </div>
                <p className="text-xs text-gray-500 truncate font-medium">{chat.lastMsg}</p>
              </div>
              {chat.unread > 0 && chat.id !== activeChatId && (
                <div className="bg-red-600 text-white text-[10px] font-black w-5 h-5 flex items-center justify-center rounded-full shadow-lg shadow-red-200">
                  {chat.unread}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Main Chat Area */}
      {activeChatId ? (
        <div className="flex-1 flex flex-col bg-gray-50/50">
          {/* Header */}
          <div className="p-4 bg-white border-b border-gray-100 flex items-center justify-between shadow-sm z-10">
            <div className="flex items-center gap-4">
              <button onClick={() => setActiveChatId(null)} className="md:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-xl"><ChevronLeft size={24} /></button>
              <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white font-black shadow-md">
                {activeChat?.name[0]}
              </div>
              <div>
                <h4 className="font-black text-gray-800 leading-none text-sm">{activeChat?.name}</h4>
                <div className="flex items-center gap-1.5 mt-1.5">
                  <div className={`w-2 h-2 rounded-full ${activeChat?.online ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                  <span className="text-[9px] font-black text-gray-400 uppercase tracking-[0.1em]">{activeChat?.online ? 'Online' : 'Offline'}</span>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-3 text-gray-400">
              <button className="p-2 hover:bg-blue-50 hover:text-blue-500 rounded-xl transition-all"><Video size={20} /></button>
              <button className="p-2 hover:bg-green-50 hover:text-green-500 rounded-xl transition-all"><Phone size={20} /></button>
              <button className="p-2 hover:bg-gray-100 rounded-xl transition-all"><MoreVertical size={20} /></button>
            </div>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6">
            <div className="flex flex-col items-center">
              <span className="text-[10px] font-black bg-white px-3 py-1 rounded-full border border-gray-100 shadow-sm text-gray-400 uppercase tracking-widest">Encrypted Chat Session</span>
            </div>

            {(messages[activeChatId] || []).map((msg) => (
              <ChatBubble key={msg.id} text={msg.text} sender={msg.sender} time={msg.time} />
            ))}
          </div>

          {/* Input */}
          <div className="p-4 bg-white border-t border-gray-100 flex items-center gap-4 shadow-2xl">
            <button className="p-2 text-gray-400 hover:text-red-500 transition-all"><Paperclip size={22} /></button>
            <div className="flex-1 relative">
              <input 
                type="text" 
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
                placeholder="Message the community..." 
                className="w-full pl-4 pr-12 py-3 bg-gray-50 rounded-2xl text-sm font-medium focus:outline-none focus:ring-2 focus:ring-red-500/10 border border-gray-100"
              />
              <button 
                onClick={handleSendMessage}
                disabled={!inputText.trim()}
