import React, { useState, useEffect } from 'react';
import { 
  Home, 
  Gamepad2, 
  MessageSquare, 
  Video, 
  Users, 
  Megaphone, 
  User,
  Activity
} from 'lucide-react';
import Dashboard from './components/Dashboard';
import GamesHub from './components/GamesHub';
import ChatSystem from './components/ChatSystem';
import Telemedicine from './components/Telemedicine';
import Community from './components/Community';
import Advocacy from './components/Advocacy';

export type Page = 'home' | 'games' | 'chat' | 'telemedicine' | 'community' | 'advocacy';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('home');

  // Sync with hash for back-button support if the environment allows it, 
  // but rely on internal state for primary rendering.
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#/', '') as Page;
      const validPages: Page[] = ['home', 'games', 'chat', 'telemedicine', 'community', 'advocacy'];
      if (validPages.includes(hash)) {
        setCurrentPage(hash);
      }
    };
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const navigate = (to: Page) => {
    setCurrentPage(to);
    // Use a non-blocking hash update
    try {
      window.location.hash = `/${to}`;
    } catch (e) {
      console.warn("Navigation hash update blocked, relying on state.");
    }
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home': return <Dashboard onNavigate={navigate} />;
      case 'games': return <GamesHub />;
      case 'chat': return <ChatSystem />;
      case 'telemedicine': return <Telemedicine />;
      case 'community': return <Community />;
      case 'advocacy': return <Advocacy />;
      default: return <Dashboard onNavigate={navigate} />;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col md:flex-row">
      {/* Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-4 py-2 flex justify-around items-center z-50 md:top-0 md:bottom-auto md:flex-col md:w-20 md:h-screen md:py-8">
        <NavItem onClick={() => navigate('home')} icon={<Home size={24} />} label="Home" active={currentPage === 'home'} />
        <NavItem onClick={() => navigate('games')} icon={<Gamepad2 size={24} />} label="Play" active={currentPage === 'games'} />
        <NavItem onClick={() => navigate('chat')} icon={<MessageSquare size={24} />} label="Chat" active={currentPage === 'chat'} />
        <NavItem onClick={() => navigate('telemedicine')} icon={<Video size={24} />} label="Care" active={currentPage === 'telemedicine'} />
        <NavItem onClick={() => navigate('community')} icon={<Users size={24} />} label="Group" active={currentPage === 'community'} />
        <NavItem onClick={() => navigate('advocacy')} icon={<Megaphone size={24} />} label="Act" active={currentPage === 'advocacy'} />
      </nav>

      <main className="flex-1 pb-20 md:pb-0 md:ml-20 overflow-y-auto">
        <header className="sticky top-0 bg-white shadow-sm px-4 py-4 flex items-center justify-between z-40">
          <div className="flex items-center gap-2 cursor-pointer" onClick={() => navigate('home')}>
            <div className="w-10 h-10 bg-red-600 rounded-full flex items-center justify-center text-white font-bold shadow-lg shadow-red-200">W</div>
            <h1 className="text-xl font-black text-gray-800 tracking-tight">Warrior Cell</h1>
          </div>
          <div className="flex items-center gap-3">
            <Activity className="text-red-500 animate-pulse" size={20} />
            <div className="bg-gray-100 p-2 rounded-xl">
              <User size={20} className="text-gray-600" />
            </div>
          </div>
        </header>

        <div className="p-4 max-w-5xl mx-auto">
          {renderPage()}
        </div>
      </main>
    </div>
  );
};

const NavItem = ({ onClick, icon, label, active }: { onClick: () => void, icon: React.ReactNode, label: string, active: boolean }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center gap-1 transition-all group ${active ? 'text-red-600' : 'text-gray-400 hover:text-red-400'}`}
  >
    <div className={`p-2 rounded-xl transition-all ${active ? 'bg-red-50' : 'group-hover:bg-gray-50'}`}>
      {icon}
    </div>
    <span className="text-[10px] font-black uppercase tracking-widest md:hidden">{label}</span>
  </button>
);

export default App;

