import React, { useState, useRef, useEffect } from 'react';
import { Send, Search, MoreVertical, Paperclip, Phone, Video, MessageSquare, ChevronLeft, Shield } from 'lucide-react';

const INITIAL_CHATS = [
  { id: '1', name: 'Lagos Warriors Support', lastMsg: 'Stay hydrated everyone!', time: '10:45 AM', unread: 3, online: true },
  { id: '2', name: 'Dr. Sarah (Hematology)', lastMsg: 'Your lab results are ready.', time: 'Yesterday', unread: 0, online: false },
  { id: '3', name: 'Global SCD Network', lastMsg: 'Meeting at 5PM GMT today!', time: 'Yesterday', unread: 0, online: true },
];

const ChatSystem: React.FC = () => {
  const [activeChatId, setActiveChatId] = useState<string | null>(INITIAL_CHATS[0].id);
  const [inputText, setInputText] = useState('');
  const [messages, setMessages] = useState<Record<string, any[]>>({
    '1': [
      { id: 'm1', text: "Hello Warriors! How's the hydration plan going?", sender: 'peer', time: '10:00 AM' },
      { id: 'm2', text: "Just finished my 2nd liter!", sender: 'peer', time: '10:05 AM' },
    ],
    '2': [{ id: 'm3', text: "Your recent tests show stable hemoglobin levels. Keep it up.", sender: 'peer', time: 'Yesterday' }],
    '3': [{ id: 'm4', text: "Reminder: World Sickle Cell Day planning starts now.", sender: 'peer', time: '9:00 AM' }]
  });

  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, activeChatId]);

  const activeChat = INITIAL_CHATS.find(c => c.id === activeChatId);

  const handleSendMessage = () => {
    if (!inputText.trim() || !activeChatId) return;

    const newMessage = {
      id: `u-${Date.now()}`,
      text: inputText,
      sender: 'user',
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => ({
      ...prev,
      [activeChatId]: [...(prev[activeChatId] || []), newMessage]
    }));
    setInputText('');

    // Simulate auto-reply after a short delay
    setTimeout(() => {
      const reply = {
        id: `r-${Date.now()}`,
        text: "That's great to hear! We are all in this together. Stay strong! 💪",
        sender: 'peer',
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      setMessages(prev => ({
        ...prev,
        [activeChatId]: [...(prev[activeChatId] || []), reply]
      }));
    }, 1500);
  };

  return (
    <div className="h-[calc(100vh-160px)] flex flex-col md:flex-row bg-white rounded-[2.5rem] shadow-xl border border-gray-100 overflow-hidden">
      {/* Sidebar */}
      <div className={`w-full md:w-80 border-r border-gray-100 flex flex-col ${activeChatId && 'hidden md:flex'}`}>
        <div className="p-6 bg-gray-50/50 border-b border-gray-100">
          <h2 className="text-2xl font-black text-gray-800 mb-4 tracking-tight">Warrior Chat</h2>
          <div className="relative">
            <Search className="absolute left-4 top-3.5 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Search conversations..." 
              className="w-full pl-12 pr-4 py-3.5 bg-white rounded-2xl border border-gray-100 text-sm focus:outline-none focus:ring-4 focus:ring-red-500/5 transition-all"
            />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto no-scrollbar">
          {INITIAL_CHATS.map((chat) => (
            <div 
              key={chat.id}
              onClick={() => setActiveChatId(chat.id)}
              className={`p-5 flex items-center gap-4 cursor-pointer hover:bg-gray-50 transition-all border-b border-gray-50/50 ${activeChatId === chat.id ? 'bg-red-50/50 border-red-100' : ''}`}
            >
              <div className="relative flex-shrink-0">
                <div className={`w-14 h-14 bg-gradient-to-br from-red-100 to-red-200 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl shadow-inner ${activeChatId === chat.id ? 'animate-pulse' : ''}`}>
                  {chat.name[0]}
                </div>
                {chat.online && <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-4 border-white rounded-full"></div>}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex justify-between items-center mb-1">
                  <h4 className="font-black text-gray-800 truncate text-sm tracking-tight">{chat.name}</h4>
                  <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">{chat.time}</span>
                </div>
                <p className="text-xs text-gray-500 truncate font-medium italic opacity-80 leading-none">{chat.lastMsg}</p>
              </div>
              {chat.unread > 0 && chat.id !== activeChatId && (
                <div className="bg-red-600 text-white text-[10px] font-black w-5 h-5 flex items-center justify-center rounded-xl shadow-lg shadow-red-200 flex-shrink-0">
                  {chat.unread}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Main Chat Area */}
      {activeChatId ? (
        <div className="flex-1 flex flex-col bg-gray-50/30">
          {/* Header */}
          <div className="p-4 bg-white border-b border-gray-100 flex items-center justify-between shadow-sm z-10">
            <div className="flex items-center gap-4">
              <button onClick={() => setActiveChatId(null)} className="md:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-xl transition-all"><ChevronLeft size={24} /></button>
              <div className="w-10 h-10 bg-red-600 rounded-xl flex items-center justify-center text-white font-black shadow-lg shadow-red-200">
                {activeChat?.name[0]}
              </div>
              <div>
                <h4 className="font-black text-gray-800 leading-none text-sm tracking-tight">{activeChat?.name}</h4>
                <div className="flex items-center gap-1.5 mt-1.5">
                  <div className={`w-2 h-2 rounded-full ${activeChat?.online ? 'bg-green-500' : 'bg-gray-300'}`}></div>
                  <span className="text-[9px] font-black text-gray-400 uppercase tracking-[0.1em]">{activeChat?.online ? 'Active Now' : 'Last seen 2h ago'}</span>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-3 text-gray-400">
              <button className="p-2.5 hover:bg-blue-50 hover:text-blue-500 rounded-xl transition-all"><Video size={20} /></button>
              <button className="p-2.5 hover:bg-green-50 hover:text-green-500 rounded-xl transition-all"><Phone size={20} /></button>
              <button className="p-2.5 hover:bg-gray-100 rounded-xl transition-all"><MoreVertical size={20} /></button>
            </div>
          </div>

          {/* Messages */}
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar">
            <div className="flex flex-col items-center mb-4">
              <div className="flex items-center gap-2 bg-white px-4 py-1.5 rounded-2xl border border-gray-100 shadow-sm">
                <Shield size={12} className="text-green-500" />
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest">End-to-End Encrypted</span>
              </div>
            </div>

            {(messages[activeChatId] || []).map((msg) => (
              <ChatBubble key={msg.id} text={msg.text} sender={msg.sender} time={msg.time} />
            ))}
          </div>

          {/* Input */}
          <div className="p-5 bg-white border-t border-gray-100 flex items-center gap-4 shadow-2xl">
            <button className="p-2.5 text-gray-400 hover:text-red-500 transition-all rounded-xl hover:bg-red-50"><Paperclip size={22} /></button>
            <div className="flex-1 relative">
              <input 
                type="text" 
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
                placeholder="Share your warrior strength..." 
                className="w-full pl-6 pr-14 py-4 bg-gray-50 rounded-2xl text-sm font-medium focus:outline-none focus:ring-4 focus:ring-red-500/5 border border-gray-100 transition-all"
              />
              <button 
                onClick={handleSendMessage}
                disabled={!inputText.trim()}
                className={`absolute right-2 top-2 p-2.5 rounded-xl transition-all ${inputText.trim() ? 'bg-red-600 text-white shadow-lg shadow-red-200 scale-100 active:scale-90' : 'bg-gray-200 text-gray-400 scale-90'}`}
              >
                <Send size={18} fill="currentColor" />
              </button>
            </div>
          </div>
        </div>
      ) : (
        <div className="flex-1 flex flex-col items-center justify-center text-gray-400 bg-gray-50/20 p-12 text-center animate-in fade-in duration-500">
          <div className="w-24 h-24 bg-white rounded-[2.5rem] shadow-2xl flex items-center justify-center mb-8 border border-gray-100 relative">
             <div className="absolute inset-0 bg-red-500/5 rounded-full blur-2xl"></div>
             <MessageSquare size={48} className="opacity-10 text-red-600 relative z-10" />
          </div>
          <h3 className="text-2xl font-black text-gray-800 mb-3 tracking-tight">Warrior Network</h3>
          <p className="text-sm font-medium max-w-xs leading-relaxed opacity-60 italic">"None of us is as strong as all of us." Select a channel to start connecting.</p>
        </div>
      )}
    </div>
  );
};

const ChatBubble = ({ text, sender, time }: any) => (
  <div className={`flex flex-col ${sender === 'user' ? 'items-end' : 'items-start'} animate-in slide-in-from-bottom-4 duration-500`}>
    <div className={`max-w-[85%] px-6 py-4 rounded-[2rem] shadow-sm text-sm font-medium leading-relaxed ${sender === 'user' ? 'bg-red-600 text-white rounded-tr-none shadow-red-100' : 'bg-white text-gray-800 rounded-tl-none border border-gray-100 shadow-gray-100/50'}`}>
      <p>{text}</p>
    </div>
    <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-2 px-3">{time}</span>
  </div>
);

export default ChatSystem;

import React, { useState } from 'react';
import { Megaphone, FileText, Send, Loader2, Sparkles, Copy, Globe, CheckCircle, Award, AlertCircle } from 'lucide-react';
import { generateAdvocacyPetition } from '../services/gemini';

const Advocacy: React.FC = () => {
  const [issue, setIssue] = useState('');
  const [region, setRegion] = useState('');
  const [petition, setPetition] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!issue || !region) return;
    setLoading(true);
    setError(null);
    try {
      const res = await generateAdvocacyPetition(issue, region);
      setPetition(res);
    } catch (e) {
      setError("The Policy Engine is temporarily overloaded. Please try again in a few moments.");
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = () => {
    if (!petition) return;
    try {
      // Use fallback if navigator.clipboard is blocked by SecurityError in blob environments
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(petition);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      } else {
        throw new Error("Clipboard API unavailable");
      }
    } catch (e) {
      // Fallback: alert the user or show a selection UI
      alert("Please manually select and copy the text below. Your browser security settings blocked automatic copying.");
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">
      <div className="bg-gradient-to-br from-indigo-700 to-purple-900 rounded-[2.5rem] p-8 text-white shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32 blur-[100px] group-hover:bg-white/10 transition-all duration-700"></div>
        <div className="relative z-10">
          <h2 className="text-4xl font-black mb-4 flex items-center gap-4 tracking-tighter leading-none">
            <Megaphone className="rotate-[-15deg] text-yellow-400 drop-shadow-lg" size={40} /> Policy Portal
          </h2>
          <p className="text-sm font-medium opacity-80 leading-relaxed max-w-sm">Empowering Warriors with AI-driven advocacy tools to change local and national policy.</p>
        </div>
      </div>

      <div className="bg-white p-8 rounded-[2.5rem] border border-gray-100 shadow-sm space-y-8">
        <div className="flex items-center gap-4">
           <div className="bg-yellow-50 p-3 rounded-2xl text-yellow-600 border border-yellow-100 shadow-inner">
             <Sparkles size={24} fill="currentColor" />
           </div>
           <div>
             <h3 className="font-black text-gray-800 uppercase tracking-widest text-xs">Advocacy Synthesizer</h3>
             <p className="text-[10px] text-gray-400 font-bold mt-1 uppercase tracking-tighter">Powered by Gemini 3 Flash</p>
           </div>
        </div>

        <div className="space-y-6">
          <div className="space-y-3">
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] ml-3">Policy Challenge</label>
            <input 
              type="text" 
              placeholder="e.g. Mandatory SCD screening in birth centers" 
              value={issue}
              onChange={(e) => setIssue(e.target.value)}
              className="w-full px-8 py-5 bg-gray-50 border border-gray-100 rounded-[1.5rem] focus:outline-none focus:ring-8 focus:ring-indigo-500/5 font-black text-gray-800 placeholder:text-gray-300 transition-all text-sm"
            />
          </div>
          <div className="space-y-3">
            <label className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em] ml-3">Location / Region</label>
            <div className="relative">
              <Globe className="absolute left-7 top-5.5 text-gray-400" size={20} />
              <input 
                type="text" 
                placeholder="e.g. Nairobi, Kenya" 
                value={region}
                onChange={(e) => setRegion(e.target.value)}
                className="w-full pl-16 pr-8 py-5 bg-gray-50 border border-gray-100 rounded-[1.5rem] focus:outline-none focus:ring-8 focus:ring-indigo-500/5 font-black text-gray-800 placeholder:text-gray-300 transition-all text-sm"
              />
            </div>
          </div>

          {error && (
            <div className="flex items-center gap-3 p-4 bg-red-50 text-red-600 rounded-2xl border border-red-100 animate-in zoom-in-95">
              <AlertCircle size={18} />
              <span className="text-xs font-bold">{error}</span>
            </div>
          )}

          <button 
            onClick={handleGenerate}
            disabled={loading || !issue || !region}
            className="w-full bg-indigo-600 text-white font-black py-6 rounded-[2rem] hover:bg-indigo-700 transition-all flex items-center justify-center gap-4 disabled:opacity-50 shadow-2xl shadow-indigo-200 uppercase tracking-[0.2em] text-sm active:scale-95 outline-none"
          >
            {loading ? <Loader2 className="animate-spin" size={20} /> : <FileText size={20} />}
            {loading ? 'Consulting Global Database...' : 'Draft Formal Petition'}
          </button>
        </div>
      </div>

      {petition && (
        <div className="bg-white p-8 rounded-[2.5rem] border-2 border-indigo-100 shadow-2xl animate-in slide-in-from-bottom-12 duration-700 relative overflow-hidden">
          <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none">
             <FileText size={160}/>
          </div>
          <div className="flex justify-between items-center mb-8 pb-6 border-b border-gray-50 relative z-10">
            <div>
              <h4 className="font-black text-indigo-800 uppercase tracking-widest text-xs">Policy Draft v1.0</h4>
              <p className="text-[9px] text-gray-400 font-bold uppercase mt-1">Ready for Legislative Submission</p>
            </div>
            <div className="flex gap-4">
              <button 
                onClick={copyToClipboard}
                className="p-4 bg-gray-50 rounded-2xl hover:bg-indigo-50 hover:text-indigo-600 transition-all active:scale-90 shadow-sm border border-gray-100"
